import re

def parse_range(header, size):
    if not header or 'bytes=' not in header:
        return None

    try:
        # Extract the part after 'bytes='
        parts_str = header.split('bytes=')[-1].split(';')[0].strip()
        if not parts_str:
            return None

        raw_ranges = [r.strip() for r in parts_str.split(',')]
        parsed_ranges = []

        for r in raw_ranges:
            if not r: continue

            # Handle suffix range (e.g., -500)
            if r.startswith('-'):
                length = int(r[1:])
                start = max(0, size - length)
                end = size - 1
                if start < size:
                    parsed_ranges.append((start, end))
                else:
                    # If -500 is requested on a 200 byte file, 
                    # it's usually treated as 0-199
                    parsed_ranges.append((0, size - 1))
            else:
                # Handle standard range (e.g., 0-499, 500-)
                parts = r.split('-')
                start_str = parts[0]

                if len(parts) == 1: # e.g., "500"
                    start = int(start_str)
                    end = size - 1
                else:
                    start = int(parts[0])
                    end_str = parts[1]
                    if not end_str: # e.g., "500-"
                        end = size - 1
                    else:
                        end = int(end_str)

                # Clamp end to size
                end = min(end, size - 1)

                if start < size and start <= end:
                    parsed_ranges.append((start, end))
                else:
                    # Mark as unsatisfiable for this specific range
                    parsed_ranges.append(None)

        # Filter out None (unsatisfiable)
        result = [r for r in parsed_ranges if r is not None]

        # If all were unsatisfiable, return None
        if not result and raw_ranges:
            return None
        return result

    except (ValueError, IndexError):
        return None
