import datetime
import re
from dateutil.relativedelta import relativedelta

def next_fire(expr, after):
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Expression must have 5 fields")

    def parse_field(field_str, min_val, max_val):
        results = set()
        raw_parts = field_str.split(',')
        for part in raw_parts:
            if '/' in part:
                base, step_str = part.split('/')
                step = int(step_str)
                if step <= 0: raise ValueError("Step must be > 0")

                # Handle range or single number
                if '-' in base:
                    start_str, end_str = base.split('-')
                    start = int(start_str)
                    end = int(end_str)
                    if start > end: raise ValueError("Start > End")
                    for i in range(start, end + 1, step):
                        results.add(i)
                else:
                    val = int(base)
                    for i in range(val, max_val + 1, step):
                        results.add(i)
            elif '-' in part:
                start_str, end_str = part.split('-')
                start, end = int(start_str), int(end_str)
                if start > end: raise ValueError("Start > End")
                for i in range(start, end + 1):
                    results.add(i)
            else:
                if part == '*':
                    results.update(range(min_val, max_val + 1))
                else:
                    results.add(int(part))

            # Filter results by valid range
            results = {r for r in results if min_val <= r <= max_val}
        return results

    # Field definitions: (min, max)
    limits = [
        (0, 59),   # minute
        (0, 23),   # hour
        (1, 31),   # day of month
        (1, 12),   # month
        (0, 6)     # day of week (0=Sun)
    ]

    try:
        m_set = parse_field(parts[0], 0, 59)
        h_set = parse_field(parts[1], 0, 23)
        dom_set = parse_field(parts[2], 1, 31)
        mon_set = parse_field(parts[3], 1, 12)
        dow_set = parse_field(parts[4], 0, 6)
    except ValueError as e:
        raise ValueError(f"Malformed expression: {e}")

    # Start searching from the next minute
    current = (after + relativedelta(minutes=1)).replace(second=0, microsecond=0)

    # Safety limit to prevent infinite loops (e.g., 100 years)
    max_years = 100
    start_year = current.year

    while current.year < start_year + max_years:
        # Check Month
        if current.month not in mon_set:
            current = (current.replace(day=1) + relativedelta(months=1)).replace(day=1)
            continue

        # Check Day of Month and Day of Week logic
        # Rule: If both are restricted, it's OR. If only one is restricted, it's that one.
        # "Restricted" means the set is not all possible values.
        dom_all = set(range(1, 32))
        dow_all = set(range(0, 7))

        dom_restricted = len(dom_set) < len(dom_all)
        dow_restricted = len(dow_set) < len(dow_set) # Wait, logic check:
        # Actually, the prompt says "when BOTH day-of-month and day-of-week are restricted"
        # A field is restricted if it's not '*'.

        is_dom_restricted = parts[2] != '*'
        is_dow_restricted = parts[4] != '*'

        match = False
        if is_dom_restricted and is_dow_restricted:
            if current.day in dom_set or current.weekday() in dow_set:
                match = True
        elif is_dom_restricted:
            if current.day in dom_set:
                match = True
        elif is_dow_restricted:
            if current.weekday() in dow_set:
                match = True
        else:
            match = True

        if match:
            # Check Hour and Minute
            if current.hour in h_set and current.minute in m_set:
                return current

        # Increment by minute
        current += relativedelta(minutes=1)

    raise ValueError("No fire time found in reasonable range.")
