const decode = (str) => str.replace(/~1/g, '/').replace(/~0/g, '~');

const get = (doc, pointer) => {
  if (pointer !== "" && !pointer.startsWith("/")) {
    throw new Error("Pointer must start with '/' or be empty");
  }

  if (pointer === "") return doc;

  const parts = pointer.split("/").slice(1);
  let current = doc;

  for (const part of parts) {
    if (current === null || typeof current !== "object") return undefined;

    const decodedPart = decode(part);
    if (Array.isArray(current)) {
      const index = parseInt(decodedPart, 10);
      if (isNaN(index) || index < 0 || index >= current.length) return undefined;
      current = current[index];
    } else {
      if (!(decodedPart in current)) return undefined;
      current = current[decodedPart];
    }
  }

  return current;
};

const set = (doc, pointer, value) => {
  if (pointer !== "" && !pointer.startsWith("/")) {
    throw new Error("Pointer must start with '/' or be empty");
  }

  if (pointer === "") {
    return value;
  }

  const parts = pointer.split("/").slice(1);
  let current = doc;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const decodedPart = decode(part);
    const isLast = i === parts.length - 1;

    if (isLast) {
      if (Array.isArray(current)) {
        const index = parseInt(decodedPart, 10);
        if (!isNaN(index)) {
          if (index >= current.length) {
            current[index] = value;
          } else {
            current[index] = value;
          }
        } else {
          current[decodedPart] = value;
        }
      } else {
        current[decodedPart] = value;
      }
    } else {
      const nextPart = parts[i + 1];
      const isNextNumeric = !isNaN(parseInt(nextPart, 10));

      if (Array.isArray(current)) {
        const index = parseInt(decodedPart, 10);
        if (isNaN(index)) {
          current[decodedPart] = current[decodedPart] || {};
          current = current[decodedPart];
        } else {
          if (current[index] === undefined) {
            current[index] = isNextNumeric ? [] : {};
          }
          current = current[index];
        }
      } else {
        if (current[decodedPart] === undefined) {
          current[decodedPart] = isNextNumeric ? [] : {};
        }
        current = current[decodedPart];
