class Emitter {
  constructor() {
    this.listeners = new Map();
  }

  on(event, fn) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const list = this.listeners.get(event);
    list.push({ fn, once: false });

    return () => this.off(event, fn);
  }

  once(event, fn) {
    return this.on(event, fn, true);
  }

  // Overloaded internal logic to handle 'once' flag
  on(event, fn, isOnce = false) {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const list = this.listeners.get(event);
    list.push({ fn, once: isOnce });

    return () => this.off(event, fn);
  }

  off(event, fn) {
    const list = this.listeners.get(event);
    if (!list) return;
    const index = list.findIndex(l => l.fn === fn);
    if (index !== -1) {
      list.splice(index, 1);
    }
  }

  emit(event, ...args) {
    const list = this.listeners.get(event);
    if (!list) return 0;

    const toInvoke = [...list];
    let count = 0;
    let firstError = null;

    for (const listener of toInvoke) {
      try {
        listener.fn(...args);
        count++;
      } catch (err) {
        if (!firstError) firstError = err;
      }
    }

    // Handle 'once' removal and cleanup
    // We iterate the original list to remove items that were marked 'once'
    // but we must be careful not to remove items added during the loop.
    // The requirement says "listeners added DURING an emit must not be invoked".
    // By using a snapshot (toInvoke), we already satisfy that.
    // "once listeners are removed before they run" implies they are removed 
    // from the registry immediately.

    const currentList = this.listeners.get(event);
    for (let i = 0; i < toInvoke.length; i++) {
      const target = toInvoke[i];
      if (target.once) {
        const idx = currentList.findIndex(l => l === target);
        if (idx !== -1) currentList.splice(idx, 1);
      }
    }

    if (firstError) throw firstError;
    return count;
