export type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends (infer U)[]
    ? DeepPartial<U>[]
    : T[P] extends object
    ? DeepPartial<T[P]>
    : T[P];
};

export function applyPatch<T extends object>(
  base: T,
  patch: DeepPartial<T>
): T {
  if (patch === null || typeof patch !== 'object') {
    return patch as unknown as T;
  }

  const result = { ...base } as any;

  for (const key in patch) {
    if (Object.prototype.hasOwnProperty.call(patch, key)) {
      const patchValue = patch[key];

      if (patchValue === undefined) {
        continue;
      }

      const baseValue = (base as any)[key];

      if (Array.isArray(patchValue)) {
        result[key] = patchValue;
      } else if (patchValue !== null && typeof patchValue === 'object' && !Array.isArray(patchValue)) {
        if (baseValue !== null && typeof baseValue === 'object' && !Array.isArray(baseValue)) {
          result[key] = applyPatch(baseValue, patchValue);
        } else {
          result[key] = applyPatch({}, patchValue);
        }
      } else {
        result[key] = patchValue;
      }
    }
  }

  return result;
}
